def solve(num: int, den: int) -> int:
    quotient, remainder = divmod(abs(num), den)
    if 2 * remainder >= den:
        quotient += 1
    return quotient if num >= 0 else -quotient

def solve(a: int, b: int) -> list:
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return [q, a - b * q]

def solve(coins: list, amount: int) -> int:
    unreachable = amount + 1
    best = [0] + [unreachable] * amount

    for total in range(1, amount + 1):
        for coin in coins:
            if coin <= total:
                best[total] = min(best[total], best[total - coin] + 1)

    return -1 if best[amount] == unreachable else best[amount]

def solve(n: int) -> str:
    ones = [
        "zero", "one", "two", "three", "four", "five", "six",
        "seven", "eight", "nine", "ten", "eleven", "twelve",
        "thirteen", "fourteen", "fifteen", "sixteen", "seventeen",
        "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety",
    ]

    def below_hundred(value: int) -> str:
        if value < 20:
            return ones[value]
        ten, unit = divmod(value, 10)
        return tens[ten] if unit == 0 else tens[ten] + "-" + ones[unit]

    def below_thousand(value: int) -> str:
        hundreds, remainder = divmod(value, 100)
        if hundreds == 0:
            return below_hundred(value)
        result = ones[hundreds] + " hundred"
        if remainder:
            result += " and " + below_hundred(remainder)
        return result

    if n < 1000:
        return below_thousand(n)

    thousands, remainder = divmod(n, 1000)
    result = ones[thousands] + " thousand"
    if remainder:
        if remainder < 100:
            result += " and " + below_hundred(remainder)
        else:
            result += " " + below_thousand(remainder)
    return result

def solve(a: str, b: str) -> int:
    def parse(version):
        core, separator, prerelease = version.partition("-")
        numbers = tuple(int(part) for part in core.split("."))
        identifiers = prerelease.split(".") if separator else []
        return numbers, identifiers, bool(separator)

    def is_numeric(identifier):
        return all("0" <= char <= "9" for char in identifier)

    core_a, pre_a, has_pre_a = parse(a)
    core_b, pre_b, has_pre_b = parse(b)

    if core_a != core_b:
        return 1 if core_a > core_b else -1

    if has_pre_a != has_pre_b:
        return -1 if has_pre_a else 1

    for part_a, part_b in zip(pre_a, pre_b):
        numeric_a = is_numeric(part_a)
        numeric_b = is_numeric(part_b)

        if numeric_a and numeric_b:
            value_a, value_b = int(part_a), int(part_b)
        elif numeric_a != numeric_b:
            return -1 if numeric_a else 1
        else:
            value_a, value_b = part_a, part_b

        if value_a != value_b:
            return 1 if value_a > value_b else -1

    if len(pre_a) != len(pre_b):
        return 1 if len(pre_a) > len(pre_b) else -1

    return 0

def solve(expression: str) -> int:
    position = 0

    def skip_spaces():
        nonlocal position
        while position < len(expression) and expression[position].isspace():
            position += 1

    def factor():
        nonlocal position
        skip_spaces()

        negative = False
        if position < len(expression) and expression[position] == "-":
            negative = True
            position += 1
            skip_spaces()

        if position < len(expression) and expression[position] == "(":
            position += 1
            value = parse_expression()
            skip_spaces()
            if position < len(expression) and expression[position] == ")":
                position += 1
        else:
            start = position
            while position < len(expression) and expression[position].isdigit():
                position += 1
            value = int(expression[start:position])

        return -value if negative else value

    def parse_term():
        nonlocal position
        value = factor()

        while True:
            skip_spaces()
            if position >= len(expression) or expression[position] not in "*/":
                return value

            operator = expression[position]
            position += 1
            right = factor()

            if operator == "*":
                value *= right
            else:
                quotient = abs(value) // abs(right)
                value = -quotient if (value < 0) != (right < 0) else quotient

    def parse_expression():
        nonlocal position
        value = parse_term()

        while True:
            skip_spaces()
            if position >= len(expression) or expression[position] not in "+-":
                return value

            operator = expression[position]
            position += 1
            right = parse_term()
            value = value + right if operator == "+" else value - right

    return parse_expression()

def solve(line: str) -> list:
    fields = []
    size = len(line)
    pos = 0

    while True:
        if pos < size and line[pos] == '"':
            pos += 1
            value = []

            while pos < size:
                if line[pos] == '"':
                    if pos + 1 < size and line[pos + 1] == '"':
                        value.append('"')
                        pos += 2
                    else:
                        pos += 1
                        break
                else:
                    value.append(line[pos])
                    pos += 1

            fields.append(''.join(value))
            if pos < size and line[pos] == ',':
                pos += 1
                if pos == size:
                    fields.append('')
                    break
            else:
                break
        else:
            end = line.find(',', pos)
            if end == -1:
                fields.append(line[pos:])
                break
            fields.append(line[pos:end])
            pos = end + 1
            if pos == size:
                fields.append('')
                break

    return fields

def solve(s: str) -> str:
    small = {"a", "an", "and", "the", "of", "in", "on", "to", "for"}
    words = s.lower().split(" ")
    nonempty = [i for i, word in enumerate(words) if word]

    for i, word in enumerate(words):
        if not word:
            continue
        if word in small and i != nonempty[0] and i != nonempty[-1]:
            continue
        words[i] = word[0].upper() + word[1:]

    return " ".join(words)

import re

def solve(s: str) -> list:
    if not s:
        return []
    return re.split(r'(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])', s)

def solve(matrix: list) -> list:
    if not matrix or not matrix[0]:
        return []

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result

def solve(nums: list) -> list:
    result = nums[:]
    i = len(result) - 2

    while i >= 0 and result[i] >= result[i + 1]:
        i -= 1

    if i < 0:
        return sorted(result)

    j = len(result) - 1
    while result[j] <= result[i]:
        j -= 1

    result[i], result[j] = result[j], result[i]
    result[i + 1:] = reversed(result[i + 1:])
    return result

def solve(y1: int, m1: int, d1: int, y2: int, m2: int, d2: int) -> int:
    def days_before_date(year: int, month: int, day: int) -> int:
        prev_year = year - 1
        total = 365 * prev_year + prev_year // 4 - prev_year // 100 + prev_year // 400
        month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
            month_lengths[1] = 29
        total += sum(month_lengths[:month - 1]) + day - 1
        return total

    return days_before_date(y2, m2, d2) - days_before_date(y1, m1, d1)

def solve(seconds: int) -> str:
    if seconds == 0:
        return "now"

    parts = []
    for name, size in (("day", 86400), ("hour", 3600), ("minute", 60), ("second", 1)):
        amount, seconds = divmod(seconds, size)
        if amount:
            unit = name if amount == 1 else name + "s"
            parts.append(f"{amount} {unit}")

    if len(parts) == 1:
        return parts[0]
    return ", ".join(parts[:-1]) + " and " + parts[-1]

def solve(s: str) -> bool:
    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        if not part or any(char < "0" or char > "9" for char in part):
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False

    return True

def solve(s: str) -> bool:
    digits = s.replace(" ", "")
    if len(digits) < 2 or any(ch < "0" or ch > "9" for ch in digits):
        return False

    total = 0
    for index, ch in enumerate(reversed(digits)):
        digit = ord(ch) - ord("0")
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0

import re

def solve(items: list) -> list:
    def natural_key(text):
        runs = re.findall(r"\d+|\D+", text)
        return tuple(
            (0, int(run)) if run[0].isdigit() else (1, run.casefold())
            for run in runs
        )

    return sorted(items, key=natural_key)

def solve(text: str, width: int) -> list:
    words = text.split()
    lines = []
    current = ""

    for word in words:
        if current and len(current) + 1 + len(word) > width:
            lines.append(current)
            current = ""
        if current:
            current += " " + word
        else:
            current = word

    if current:
        lines.append(current)

    return lines

def solve(digits: str, b1: int, b2: int) -> str:
    alphabet = "0123456789abcdefghijklmnopqrstuvwxyz"

    value = 0
    for digit in digits:
        value = value * b1 + alphabet.index(digit)

    if value == 0:
        return "0"

    result = []
    while value:
        value, remainder = divmod(value, b2)
        result.append(alphabet[remainder])

    return "".join(reversed(result))
